// Bounded experiment: current Q4 dot/reduction with shape specialization,
// single-stage asynchronous transport and optional next-block input prefetch.
#include "cuda/glm_vq_linear.cuh"
__device__ __forceinline__ void q4_acc_reg(const uint8_t *block, const float4 lo, const float4 hi, float *sum) {
    const uint32_t lane = threadIdx.x & 31, group = lane >> 3, offset = (lane & 7) * 4;
    const uint4 h = *(const uint4 *)block;
    const uint32_t packed = *(const uint32_t *)(block + 16 + lane * 4);
    const float d = __half2float(__ushort_as_half(h.x & 65535u));
    const float dm = __half2float(__ushort_as_half(h.x >> 16));
    float sl, ml, sh, mh;
    glmvq_q4_scales(h, group * 2, &sl, &ml);
    glmvq_q4_scales(h, group * 2 + 1, &sh, &mh);
    sl *= d; sh *= d; ml *= dm; mh *= dm;
    float low[4], high[4];
    #pragma unroll
    for (uint32_t j = 0; j < 4; j++) {
        const uint32_t byte = packed >> (j * 8) & 255u;
        low[j] = sl * (byte & 15u) - ml;
        high[j] = sh * (byte >> 4) - mh;
    }
    *sum = fmaf(low[0], lo.x, *sum); *sum = fmaf(low[1], lo.y, *sum);
    *sum = fmaf(low[2], lo.z, *sum); *sum = fmaf(low[3], lo.w, *sum);
    *sum = fmaf(high[0], hi.x, *sum); *sum = fmaf(high[1], hi.y, *sum);
    *sum = fmaf(high[2], hi.z, *sum); *sum = fmaf(high[3], hi.w, *sum);
}

template <uint32_t COLS, uint32_t SPLIT, bool ASYNC, bool PREFETCH>
__global__ void __launch_bounds__(256, 4) q4_refine(const uint8_t *weight,
        const float *input, float *out, uint32_t rows) {
    extern __shared__ uint4 staged[];
    __shared__ float partial[GLMVQ_Q4_WARPS];
    const uint32_t lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
    constexpr uint32_t rpb = GLMVQ_Q4_WARPS / SPLIT, blocks = COLS / GLMVQ_Q4_BLOCK;
    constexpr uint32_t row16 = blocks * (GLMVQ_Q4_BYTES / sizeof(uint4));
    const uint32_t local = warp / SPLIT, part = warp % SPLIT;
    const uint32_t first = blockIdx.x * rpb, row = first + local;
    const uint32_t count = min(rpb, rows - first) * row16;
    const uint4 *src = (const uint4 *)weight + (uint64_t)first * row16;
    for (uint32_t i = threadIdx.x; i < count; i += blockDim.x) {
        if constexpr (ASYNC) { __pipeline_memcpy_async(staged + i, src + i, sizeof(uint4)); }
        else { staged[i] = __ldcs(src + i); }
    }
    if constexpr (ASYNC) { __pipeline_commit(); __pipeline_wait_prior(0); }
    __syncthreads();
    float sum = 0;
    if (row < rows) {
        const uint8_t *w = (const uint8_t *)(staged + local * row16);
        if constexpr (PREFETCH) {
            constexpr uint32_t stride = SPLIT * GLMVQ_Q4_BLOCK;
            const float *x = input + part * GLMVQ_Q4_BLOCK + (lane >> 3) * 64 + (lane & 7) * 4;
            float4 lo = *(const float4 *)x, hi = *(const float4 *)(x + 32);
            #pragma unroll 1
            for (uint32_t b = part; b < blocks; b += SPLIT, x += stride) {
                float4 next_lo{}, next_hi{};
                if (b + SPLIT < blocks) {
                    next_lo = *(const float4 *)(x + stride);
                    next_hi = *(const float4 *)(x + stride + 32);
                }
                q4_acc_reg(w + b * GLMVQ_Q4_BYTES, lo, hi, &sum);
                lo = next_lo; hi = next_hi;
            }
        } else {
            #pragma unroll 1
            for (uint32_t b = part; b < blocks; b += SPLIT) {
                glmvq_q4_acc<1>(w + b * GLMVQ_Q4_BYTES, input, COLS,
                    b * GLMVQ_Q4_BLOCK, 1, &sum);
            }
        }
    }
    for (int stride = 16; stride; stride >>= 1) { sum += __shfl_xor_sync(0xffffffffu, sum, stride); }
    if (!lane) { partial[warp] = sum; }
    __syncthreads();
    if (row >= rows || lane || part) { return; }
    float value = 0;
    #pragma unroll
    for (uint32_t p = 0; p < SPLIT; p++) { value += partial[warp + p]; }
    out[row] = __bfloat162float(__float2bfloat16_rn(value));
}

template <uint32_t COLS, uint32_t SPLIT>
static void q4_launch(const uint8_t *w, const float *x, float *y, uint32_t rows, uint32_t mode) {
    constexpr uint32_t rpb = GLMVQ_Q4_WARPS / SPLIT;
    constexpr uint32_t shared = rpb * COLS / GLMVQ_Q4_BLOCK * GLMVQ_Q4_BYTES;
    const uint32_t grid = (rows + rpb - 1) / rpb;
    if (mode == 1) { q4_refine<COLS,SPLIT,false,false><<<grid,256,shared>>>(w,x,y,rows); }
    if (mode == 2) { q4_refine<COLS,SPLIT,true,false><<<grid,256,shared>>>(w,x,y,rows); }
    if (mode == 3) { q4_refine<COLS,SPLIT,true,true><<<grid,256,shared>>>(w,x,y,rows); }
}
extern "C" int bench_q4_refine(const uint8_t *packed, const float *input, float *output,
        uint32_t rows, uint32_t cols, uint32_t tokens, uint32_t repeats, uint32_t mode, float *ms) {
    if (!packed || !input || !output || !ms || !rows || !cols || cols % GLMVQ_Q4_BLOCK ||
        !tokens || tokens > GLMVQ_Q4_WARPS || !repeats || mode > 3 || tokens != 1 || (cols != 4096 && cols != 8192)) { return -1; }
    constexpr uint64_t rotation_bytes = 64ull << 20;
    constexpr uint32_t warmup = 32;
    const uint64_t wb = (uint64_t)rows * cols / GLMVQ_Q4_BLOCK * GLMVQ_Q4_BYTES;
    const uint32_t copies = (uint32_t)((rotation_bytes + wb - 1) / wb);
    const uint64_t xb = (uint64_t)tokens * cols * sizeof(float), yb = (uint64_t)tokens * rows * sizeof(float);
    uint8_t *w = nullptr;
    float *x = nullptr, *y = nullptr;
    cudaEvent_t begin = nullptr, end = nullptr;
    glmvq_q4_config config;
    cudaError_t err = glmvq_q4_prepare(&config, GLMVQ_Q4_STAGE);
    if (err == cudaSuccess) { err = cudaMalloc(&w, wb * copies); }
    if (err == cudaSuccess) { err = cudaMalloc(&x, xb); }
    if (err == cudaSuccess) { err = cudaMalloc(&y, yb); }
    if (err == cudaSuccess) { err = cudaEventCreate(&begin); }
    if (err == cudaSuccess) { err = cudaEventCreate(&end); }
    for (uint32_t i = 0; i < copies && err == cudaSuccess; i++) {
        err = cudaMemcpy(w + i * wb, packed, wb, cudaMemcpyHostToDevice);
    }
    if (err == cudaSuccess) { err = cudaMemcpy(x, input, xb, cudaMemcpyHostToDevice); }
    // A one-launch request is for NCU, which supplies its own replay protocol.
    for (uint32_t i = 0; i < (repeats == 1 ? 0u : warmup) && err == cudaSuccess; i++) {
        if (mode == 0) {
            err = glmvq_q4_decode(w + i % copies * wb, x, y, rows, cols, tokens, 0, &config);
        } else {
            if (cols == 4096) { q4_launch<4096,1>(w + i % copies * wb,x,y,rows,mode); }
            else { q4_launch<8192,2>(w + i % copies * wb,x,y,rows,mode); }
            err = cudaGetLastError();
        }
    }
    if (err == cudaSuccess) { err = cudaEventRecord(begin); }
    for (uint32_t i = 0; i < repeats && err == cudaSuccess; i++) {
        if (mode == 0) {
            err = glmvq_q4_decode(w + i % copies * wb, x, y, rows, cols, tokens, 0, &config);
        } else {
            if (cols == 4096) { q4_launch<4096,1>(w + i % copies * wb,x,y,rows,mode); }
            else { q4_launch<8192,2>(w + i % copies * wb,x,y,rows,mode); }
            err = cudaGetLastError();
        }
    }
    if (err == cudaSuccess) { err = cudaEventRecord(end); }
    if (err == cudaSuccess) { err = cudaEventSynchronize(end); }
    if (err == cudaSuccess) { err = cudaEventElapsedTime(ms, begin, end); }
    if (err == cudaSuccess) { *ms /= repeats; }
    if (err == cudaSuccess) { err = cudaMemcpy(output, y, yb, cudaMemcpyDeviceToHost); }
    if (end) { cudaEventDestroy(end); }
    if (begin) { cudaEventDestroy(begin); }
    cudaFree(y); cudaFree(x); cudaFree(w);
    return (int)err;
}
